import{_ as d,o as e,c as r,a3 as n}from"./chunks/framework.MGD2uYU7.js";const l=JSON.parse('{"title":"Business Rules + Permission Matrix — AnPhucRealEstate v1","description":"","frontmatter":{},"headers":[],"relativePath":"guide/08-business-rules-permissions.md","filePath":"guide/08-business-rules-permissions.md","lastUpdated":null}'),o={name:"guide/08-business-rules-permissions.md"};function i(a,t,h,c,s,g){return e(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="business-rules-permission-matrix-—-anphucrealestate-v1" tabindex="-1">Business Rules + Permission Matrix — AnPhucRealEstate v1 <a class="header-anchor" href="#business-rules-permission-matrix-—-anphucrealestate-v1" aria-label="Permalink to &quot;Business Rules + Permission Matrix — AnPhucRealEstate v1&quot;">​</a></h1><p><strong>Status</strong>: In Review — <strong>Author</strong>: Alex (PM) + Pháp chế (chờ sign-off OQ-4) — <strong>Updated</strong>: 2026-10-10 — <strong>v1.4</strong> (M-003 media foundation: BR-IDT-08 storage PUBLIC/PRIVATE + presigned TTL, §9 thêm row files 64/65/66 + ảnh dự án 67/68, BR-ADM-01 ghi nhận <code>PROJECT_IMAGE_ADD</code>/<code>PROJECT_IMAGE_REMOVE</code>) — v1.3 (US-HS-01 bổ sung DELETE: BR-ADM-01 ghi nhận <code>PROJECT_DELETE</code> — hard delete, diff <code>{before}</code>; §9 matrix đổi thành tạo/sửa/xóa dự án) — v1.2 (M-002/US-HS-01 backend: BR-ADM-01 ghi nhận audit <code>PROJECT_CREATE</code>/<code>PROJECT_UPDATE</code>, §9 thêm row admin dự án endpoint 51) — v1.1 (review pass: thêm BR-ADM-04 reset password ADMIN, đồng bộ BR-PAY-05/BR-AU-17 với F-07/UC-08) <strong>Quy tắc sử dụng</strong>: developer <strong>chỉ implement đúng ID</strong> được reference trong story; không tự suy đoán giá trị/ngoại lệ. Giá trị &quot;config&quot; = seed có thể đổi bởi ADMIN (table config nếu cần), giá trị &quot;hard&quot; = enforce trong code. Số liệu đầu tiên là <strong>giả định PM để dev triển khai</strong>, chờ ban điều hành duyệt (OQ-8) — đổi số không đổi cấu trúc rule.</p><h2 id="_1-nhom-br-idt-—-identity" tabindex="-1">1. Nhóm BR-IDT — Identity <a class="header-anchor" href="#_1-nhom-br-idt-—-identity" aria-label="Permalink to &quot;1. Nhóm BR-IDT — Identity&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Rule</th><th>Loại</th><th>From UC/FR</th></tr></thead><tbody><tr><td>BR-IDT-01</td><td>Email unique toàn hệ thống, normalize lowercase trước check</td><td>hard</td><td>UC-01 / IDT-01</td></tr><tr><td>BR-IDT-02</td><td>Password ≥8 ký tự, ≥1 hoa, ≥1 số, ≥1 ký tự đặc biệt; hash argon2id</td><td>hard</td><td>IDT-01</td></tr><tr><td>BR-IDT-03</td><td>Access token 15 phút; refresh 7 ngày rotation; reuse ⇒ thu hồi cả family</td><td>hard</td><td>IDT-02</td></tr><tr><td>BR-IDT-04</td><td>Chỉ ADMIN suspend/activate; lý do 5–500 ký tự bắt buộc; luôn audit</td><td>hard</td><td>UC-12 / ADM-03</td></tr><tr><td>BR-IDT-05</td><td><strong>Cấm suspend</strong> user có registration <code>ACTIVE</code> trong phiên <code>IN_PROGRESS</code>; vi phạm giữa phiên xử bằng <code>auction_privilege</code> sau khi phiên kết thúc</td><td>hard</td><td>UC-12 EF</td></tr><tr><td>BR-IDT-06</td><td>1 CCCD (hash) chỉ thuộc về <strong>đúng 1</strong> user ở trạng thái KYC APPROVED</td><td>hard</td><td>KYC-01</td></tr><tr><td>BR-IDT-07</td><td>User <code>SUSPENDED</code>: login được nhưng mọi mutation nghiệp vụ 403 <code>USER_SUSPENDED</code>; read-only public vẫn được</td><td>hard</td><td></td></tr><tr><td>BR-IDT-08</td><td>Media foundation (M-003, endpoints 64/65/66 docs/06 §4.11): upload phải đăng nhập; <code>visibility=PUBLIC</code> <strong>chỉ ảnh</strong> (jpeg/png/webp/gif ≤10MB) — object nằm bucket public, URL cố định; mọi thứ khác (tài liệu, hợp đồng: pdf/doc/docx/xls/xlsx ≤25MB) bắt buộc <code>PRIVATE</code> — không có đường đọc anonymous, chỉ chủ sở hữu/ADMIN lấy được presigned URL qua endpoint 65 (TTL <code>S3_PRESIGN_TTL_SEC</code> default 900s); đọc/xóa file không phải của mình → 404 <code>FILE_NOT_FOUND</code> (chống probe tồn tại — rule 3 docs/06 §6)</td><td>hard</td><td></td></tr></tbody></table><h2 id="_2-nhom-br-kyc" tabindex="-1">2. Nhóm BR-KYC <a class="header-anchor" href="#_2-nhom-br-kyc" aria-label="Permalink to &quot;2. Nhóm BR-KYC&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Rule</th><th>Loại</th></tr></thead><tbody><tr><td>BR-KYC-01</td><td>CCCD đúng 12 chữ số; tuổi ≥18 tại thời điểm nộp (server clock)</td><td>hard</td></tr><tr><td>BR-KYC-02</td><td>Họ tên user và tên trên CCCD phải <strong>trùng khít không dấu/ CÓ dấu chuẩn NFC</strong> — ADMIN đối chiếu trực quan khi duyệt (v1 manual, OQ tương lai API 1411/dữ liệu dân cư)</td><td>hard (quy trình)</td></tr><tr><td>BR-KYC-03</td><td>2 ảnh CCCD bắt buộc, JPEG/PNG/WEBP, ≤5MB/ảnh, không che góc</td><td>soft (FE) + format (BE)</td></tr><tr><td>BR-KYC-04</td><td>REJECTED phải có reason 10–500 ký tự, hiển thị nguyên văn cho user</td><td>hard</td></tr><tr><td>BR-KYC-05</td><td>Tại 1 thời điểm user chỉ có 1 application <code>PENDING</code></td><td>hard</td></tr><tr><td>BR-KYC-06</td><td>Tối đa 3 application (kể cả resubmit) trong 30 ngày rolling</td><td>hard</td></tr><tr><td>BR-KYC-07</td><td>Retention: REJECTED quá 180 ngày → purge media + nullify CCCD (job); tài khoản CLOSED quá 365 ngày → purge toàn bộ dữ liệu định danh</td><td>hard (job)</td></tr><tr><td>BR-KYC-08</td><td>KYC APPROVED là <strong>điều kiện tiên quyết</strong> cho: tạo tin (BR-HS-01), đăng ký đấu giá (BR-AU-05), đặt lịch xem (FR-VW-01)</td><td>hard</td></tr></tbody></table><h2 id="_3-nhom-br-hs-—-housing" tabindex="-1">3. Nhóm BR-HS — Housing <a class="header-anchor" href="#_3-nhom-br-hs-—-housing" aria-label="Permalink to &quot;3. Nhóm BR-HS — Housing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Rule</th><th>Loại</th></tr></thead><tbody><tr><td>BR-HS-01</td><td>Chỉ user KYC APPROVED tạo/submit tin</td><td>hard</td></tr><tr><td>BR-HS-02</td><td>Người đăng phải là chủ sở hữu: <code>cert_owner_name_match</code> (ADMIN tick khi duyệt) phải true trước APPROVE; tên trên sổ khớp họ tên KYC</td><td>hard (quy trình duyệt)</td></tr><tr><td>BR-HS-03</td><td><code>certSerial</code> (số sổ) unique toàn sàn; đã claim bởi tin nào thì <strong>không đổi, không un-link</strong> qua self-service — sai phải ticket CS/ADMIN xóa tin + purge, audit</td><td>hard</td></tr><tr><td>BR-HS-04</td><td>Diện tích 15–500 m²; CHECK DB</td><td>hard</td></tr><tr><td>BR-HS-05</td><td>Giá rao 500.000.000–20.000.000.000 VND; CHECK DB</td><td>config biên</td></tr><tr><td>BR-HS-06</td><td>Đơn giá = floor(price/area) ≤ <code>project.resale_price_cap_m2</code> (trần bán lại NOXH theo dự án) — validate lúc submit &amp; re-validate lúc ADMIN approve</td><td>hard; nguồn cap: OQ-4</td></tr><tr><td>BR-HS-07</td><td>Tin <strong>không tự đăng</strong> — bắt buộc ADMIN duyệt (APPROVE) mới LISTED</td><td>hard</td></tr><tr><td>BR-HS-08</td><td>Reject phải reason 10–500 ký tự; user sửa → submit lại từ đầu</td><td>hard</td></tr><tr><td>BR-HS-09</td><td>Giới hạn 5 lần submit/30 ngày rolling (<code>reject_count_30d</code>)</td><td>hard</td></tr><tr><td>BR-HS-10</td><td>Ảnh 3–15 (duyệt 1 ảnh cover bắt buộc đánh dấu), tài liệu pháp lý 1–6 PDF ≤10MB</td><td>hard</td></tr><tr><td>BR-HS-11</td><td>Tin <code>RESERVED</code>/<code>SOLD</code>: khóa mọi sửa/rút bởi owner; <code>LISTED</code> owner rút được → <code>WITHDRAWN</code> (terminal)</td><td>hard</td></tr><tr><td>BR-HS-12</td><td>Public payload không bao giờ chứa certSerial (kể cả masked cho non-owner) và không chứa tài liệu pháp lý; non-owner chỉ thấy <code>legalVerified</code> + legalType</td><td>hard (NFR-S-05)</td></tr></tbody></table><h2 id="_4-nhom-br-au-—-auction-trung-tam-nghiep-vu" tabindex="-1">4. Nhóm BR-AU — Auction (trung tâm nghiệp vụ) <a class="header-anchor" href="#_4-nhom-br-au-—-auction-trung-tam-nghiep-vu" aria-label="Permalink to &quot;4. Nhóm BR-AU — Auction (trung tâm nghiệp vụ)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Rule</th><th>Loại</th></tr></thead><tbody><tr><td>BR-AU-01</td><td>Phiên chỉ do <strong>ADMIN</strong> tạo &amp; vận hành (v1); seller không tự mở</td><td>hard scope</td></tr><tr><td>BR-AU-02</td><td>1 phiên = 1 listing; listing chỉ tham gia 1 phiên đang sống (<code>state NOT IN FAILED/CANCELLED</code>) — partial unique</td><td>hard</td></tr><tr><td>BR-AU-03</td><td>Public ≥ <strong>7 ngày</strong> trước start (notice_at ≤ start_at − 7d), kiểm tại publish</td><td>hard</td></tr><tr><td>BR-AU-04</td><td>Đóng đăng ký = start_at − <strong>24h</strong>; sau deadline registration endpoint → 410</td><td>hard</td></tr><tr><td>BR-AU-05</td><td>Điều kiện đăng ký: KYC APPROVED, user ACTIVE + privilege GRANTED, không phải owner listing, chưa có registration (unique)</td><td>hard</td></tr><tr><td>BR-AU-06</td><td>Deposit = floor(opening_price × deposit_percent/100), <strong>min 10.000.000</strong>; deposit_percent config 1–20 default 5</td><td>config</td></tr><tr><td>BR-AU-07</td><td>Cọc phải PAID trước regDeadline, không ⇒ REJECTED (job cuối window); số lần tạo payment intent không giới hạn trong window</td><td>hard</td></tr><tr><td>BR-AU-08</td><td>Bid amount ≥ current_price + step_price; số nguyên VND, max 1.000.000.000.000; idempotency per attempt</td><td>hard</td></tr><tr><td>BR-AU-09</td><td>step_price config theo phiên, CHECK 1–20% opening, <strong>bất biến sau publish</strong></td><td>hard</td></tr><tr><td>BR-AU-10</td><td><strong>Bid đã nhận không rút, không sửa</strong> (append-only)</td><td>hard</td></tr><tr><td>BR-AU-11</td><td>Bid chỉ khi state=IN_PROGRESS &amp;&amp; registration ACTIVE &amp;&amp; privilege GRANTED; mỗi user max 1 bid/giây</td><td>hard</td></tr><tr><td>BR-AU-12</td><td>Anti-snipe: bid hợp lệ khi <code>now &gt; effective_end_at − 60s</code> ⇒ <code>effective_end_at += 60s</code>, không giới hạn lần; audit mỗi lần extend</td><td>hard</td></tr><tr><td>BR-AU-13</td><td>Kết thúc = <code>now ≥ effective_end_at &amp;&amp; now − last_valid_bid_at ≥ 60s</code> (job 5s); 0 bid ⇒ FAILED, ≥1 ⇒ AWARDED cho leader</td><td>hard</td></tr><tr><td>BR-AU-14</td><td>auction_fee = floor(hammer × fee_percent/100), fee_percent config 0–5 default 1.5; tổng payable = hammer + fee − deposit; <strong>mọi phép tính floor, integer</strong></td><td>config</td></tr><tr><td>BR-AU-15</td><td>payBy = result + <strong>24h</strong>; quá hạn ⇒ order EXPIRED, registration FORFEITED (cọc không hoàn), privilege SUSPENDED, listing → LISTED</td><td>hard</td></tr><tr><td>BR-AU-16</td><td>Privilege SUSPENDED: không đăng ký/bid phiên mới cho tới khi ADMIN restore (lý do audit); <strong>không</strong> ảnh hưởng order đã EXPIRED</td><td>hard</td></tr><tr><td>BR-AU-17</td><td>User bị suspend giữa phiên (hy hữu, chỉ khi không ACTIVE registration — đã có BR-IDT-05): bid đã ghi <strong>giữ nguyên giá trị</strong>, không được bid tiếp</td><td>hard</td></tr><tr><td>BR-AU-18</td><td>v1 <strong>không tự trao giải cho người thứ hai</strong> khi winner vi phạm — listing về LISTED, tái đấu giá là phiên mới</td><td>hard scope (OQ-4)</td></tr><tr><td>BR-AU-19</td><td>Cancel phiên: chỉ DRAFT/PUBLISHED; refund 100% cọc ACTIVE trong 3 ngày làm việc; listing → LISTED; NTF toàn bộ registrants</td><td>hard</td></tr><tr><td>BR-AU-20</td><td>Bid feed public hiển thị <strong>pseudonym</strong>, không hiển thị user_id/số điện/email; participant không biết nhau ngoài pseudonym</td><td>hard</td></tr><tr><td>BR-AU-21</td><td>Thời điểm server (<code>server_received_at</code>) là trọng tài mọi tie-break/race; đồng hồ client chỉ để hiển thị countdown (offset-sync <code>X-Server-Time</code>)</td><td>hard</td></tr></tbody></table><h2 id="_5-nhom-br-pay" tabindex="-1">5. Nhóm BR-PAY <a class="header-anchor" href="#_5-nhom-br-pay" aria-label="Permalink to &quot;5. Nhóm BR-PAY&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Rule</th><th>Loại</th></tr></thead><tbody><tr><td>BR-PAY-01</td><td>Toàn bộ số tiền integer VND; đối soát <code>payments.amount</code> với <code>ref</code> (deposit=deposit_amount, settlement=payable_amount, subscription=package.price) — lệch ⇒ RECON_FAILED, không auto-apply</td><td>hard</td></tr><tr><td>BR-PAY-02</td><td>Webhook: verify checksum trước mọi xử lý; idempotent theo <code>gateway_txn_ref</code> unique; payload lưu raw có redact</td><td>hard</td></tr><tr><td>BR-PAY-03</td><td>Payment intent <code>INITIATED</code> hết hạn sau 6h ⇒ <code>EXPIRED</code> (job); user tạo intent mới trong window nghiệp vụ</td><td>hard</td></tr><tr><td>BR-PAY-04</td><td>Manual transfer: ADMIN confirm khi content bill khớp <code>ANPHUC &lt;paymentId&gt;</code> <strong>và</strong> số tiền khớp; bắt buộc ghi <code>confirmed_by</code>, audit; SLA mục tiêu ≤2h giờ làm việc</td><td>hard+SLA</td></tr><tr><td>BR-PAY-05</td><td>Hoàn cọc loser: tự động job <code>auction end + 3 ngày làm việc</code>; gateway refund hoặc manual; state → <code>REFUNDED</code> + NTF</td><td>hard</td></tr><tr><td>BR-PAY-06</td><td>FORFEITED deposit: không refund; ghi audit <code>ORDER_FORFEIT</code> + biên bản ops ngoài hệ thống</td><td>hard</td></tr><tr><td>BR-PAY-07</td><td>Order đã <code>PAID</code> chỉ ADMIN chuyển <code>COMPLETED</code> (bước xác nhận đối chiếu); <strong>không</strong> đổi số tiền; cancel+refund → <code>CANCELLED_REFUNDED</code> (manual, audit)</td><td>hard</td></tr></tbody></table><h2 id="_6-nhom-br-pkg" tabindex="-1">6. Nhóm BR-PKG <a class="header-anchor" href="#_6-nhom-br-pkg" aria-label="Permalink to &quot;6. Nhóm BR-PKG&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Rule</th><th>Loại</th></tr></thead><tbody><tr><td>BR-PKG-01</td><td>Danh mục v1: FREE (0đ, 2 tin), VIP_STANDARD (500.000đ/30 ngày, 10 tin), VIP_PRO (1.500.000đ/30 ngày, 50 tin) — giá chờ OQ-8</td><td>config</td></tr><tr><td>BR-PKG-02</td><td>Đếm quota: tin có state ∈ {LISTED, RESERVED} hoặc SOLD trong 30 ngày gần nhất; enforce <strong>lúc submit</strong>, không cắt tin đang sống khi hết gói</td><td>hard</td></tr><tr><td>BR-PKG-03</td><td>Gia hạn cùng package ⇒ cộng dồn <code>ends_at += 30d</code>; đổi package ⇒ cũ <code>SUPERSEDED</code> ngay, mới ACTIVE, <strong>không refund phần cũ</strong> (modal cảnh báo trước thanh toán)</td><td>hard</td></tr><tr><td>BR-PKG-04</td><td>Không refund/hủy giữa chu kỳ trong v1</td><td>hard scope</td></tr><tr><td>BR-PKG-05</td><td>Hết hạn: job giờ lẻ <code>ACTIVE &amp;&amp; now &gt; ends_at</code> → <code>EXPIRED</code>; badge VIP trên tin biến mất ở lần đọc kế tiếp</td><td>hard</td></tr><tr><td>BR-PKG-06</td><td><code>featured</code> sort = VIP trước rồi newest — <strong>quy tắc tĩnh, không AI</strong> (non-goal v1)</td><td>hard</td></tr></tbody></table><h2 id="_7-nhom-br-vw" tabindex="-1">7. Nhóm BR-VW <a class="header-anchor" href="#_7-nhom-br-vw" aria-label="Permalink to &quot;7. Nhóm BR-VW&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Rule</th><th>Loại</th></tr></thead><tbody><tr><td>BR-VW-01</td><td>Slot ∈ [now+24h, now+14d], giờ 08:00–20:00 Asia/Ho_Chi_Minh; validate server-side</td><td>hard</td></tr><tr><td>BR-VW-02</td><td>Tối đa 3 request <code>PENDING</code>/user; 1 request PENDING/PENDING-confirmed mỗi cặp user×listing</td><td>hard</td></tr><tr><td>BR-VW-03</td><td>Chủ nhà phản hồi ≤24h (mục tiêu SLA ops); quá <code>slot_at + 2h</code> chưa COMPLETE ⇒ <code>EXPIRED</code> (job)</td><td>hard</td></tr><tr><td>BR-VW-04</td><td>Chỉ tin <code>LISTED</code> nhận đặt lịch; tin RESERVED/ENDED → 409</td><td>hard</td></tr></tbody></table><h2 id="_8-nhom-br-adm" tabindex="-1">8. Nhóm BR-ADM <a class="header-anchor" href="#_8-nhom-br-adm" aria-label="Permalink to &quot;8. Nhóm BR-ADM&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Rule</th><th>Loại</th></tr></thead><tbody><tr><td>BR-ADM-01</td><td>100% mutation ADMIN có <code>audit_logs</code> (actor, action, entity, diff redact PII, ip, trace_id) — áp dụng cho dự án: <code>PROJECT_CREATE</code> (diff <code>{after}</code>), <code>PROJECT_UPDATE</code> (diff <code>{before, after}</code> theo field đổi; PATCH không đổi gì → không ghi, chống nhiễu), <code>PROJECT_DELETE</code> (diff <code>{before}</code> full snapshot — hard delete, audit là dấu vết duy nhất), <code>PROJECT_IMAGE_ADD</code>/<code>PROJECT_IMAGE_REMOVE</code> (M-003 — entity <code>project_image</code>, diff <code>{after}</code>/<code>{before}</code> gồm url + originalName)</td><td>hard</td></tr><tr><td>BR-ADM-02</td><td>audit_logs append-only — không API UPDATE/DELETE, DB grant chỉ INSERT/SELECT</td><td>hard</td></tr><tr><td>BR-ADM-03</td><td>SLA duyệt: KYC ≤48h, listing ≤24h giờ làm việc; quá hạn badge đỏ ở queue + alert (FR-STAT-01)</td><td>target ops</td></tr><tr><td>BR-ADM-04</td><td>ADMIN reset password user theo yêu cầu CS (UC-01 AF-3, FR-IDT-07): <code>{reason}</code> 5–500 ký tự bắt buộc; sinh mật khẩu tạm <strong>1 lần dùng</strong> (force-change ở lần đăng nhập đầu — cột <code>users.password_must_change</code>); thu hồi toàn bộ refresh token family của user đó; audit <code>USER_RESET_PASSWORD</code> <strong>không</strong> lưu mật khẩu tạm trong diff; user SUSPENDED không được reset (403)</td><td>hard</td></tr></tbody></table><h2 id="_9-permission-matrix" tabindex="-1">9. Permission Matrix <a class="header-anchor" href="#_9-permission-matrix" aria-label="Permalink to &quot;9. Permission Matrix&quot;">​</a></h2><p>Ký hiệu: ✅ cho phép · ⛔ từ chối (403) · 👁 read-only · 🚫 theo resource (ownership — vi phạm trả 404). GUEST = không JWT.</p><table tabindex="0"><thead><tr><th>Action (endpoint)</th><th>GUEST</th><th>USER</th><th>USER (owner của resource)</th><th>ADMIN</th></tr></thead><tbody><tr><td>Browse listings/projects/auctions public</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Xem certSerial / listing documents</td><td>⛔</td><td>⛔</td><td>🚫 ✅</td><td>✅ (duyệt)</td></tr><tr><td>Đăng ký / login / refresh</td><td>✅</td><td>✅</td><td>—</td><td>✅</td></tr><tr><td>Sửa hồ sơ mình</td><td>⛔</td><td>✅</td><td>—</td><td>⛔ (không sửa hộ; ops)</td></tr><tr><td>Reset password user (BR-ADM-04, endpoint 63)</td><td>⛔</td><td>⛔</td><td>⛔</td><td>✅ (reason bắt buộc)</td></tr><tr><td>Đổi role / status user</td><td>⛔</td><td>⛔</td><td>⛔</td><td>✅ (BR-IDT-04)</td></tr><tr><td>Nộp KYC</td><td>⛔</td><td>✅</td><td>—</td><td>— (admin không cần/không được nộp hộ)</td></tr><tr><td>Duyệt KYC</td><td>⛔</td><td>⛔</td><td>⛔</td><td>✅</td></tr><tr><td>Tạo/sửa/submit/withdraw tin</td><td>⛔</td><td>⛔</td><td>✅ 🚫 (chỉ tin mình, trạng thái machine docs/08 §10.1)</td><td>⛔ (không sửa nội dung tin của user — chỉ decision)</td></tr><tr><td>Duyệt tin (approve/reject)</td><td>⛔</td><td>⛔</td><td>⛔</td><td>✅</td></tr><tr><td>Tạo/sửa/xóa <strong>dự án</strong> NOXH — <code>POST /admin/projects</code> · <code>PATCH /admin/projects/{id}</code> · <code>DELETE /admin/projects/{id}</code> (endpoint 51; mọi mutation ghi audit <code>PROJECT_CREATE</code>/<code>PROJECT_UPDATE</code>/<code>PROJECT_DELETE</code> — BR-ADM-01; USER gọi → 403, guest → 401)</td><td>⛔</td><td>⛔</td><td>⛔</td><td>✅</td></tr><tr><td>Upload file của mình — <code>POST /files</code> (64, BR-IDT-08)</td><td>⛔</td><td>✅</td><td>—</td><td>✅</td></tr><tr><td>Đọc link file — <code>GET /files/{id}/url</code> (65): PUBLIC ai đăng nhập cũng đọc được URL cố định; PRIVATE presigned</td><td>⛔</td><td>👁 (PUBLIC)</td><td>✅ (PRIVATE)</td><td>✅ (mọi PRIVATE)</td></tr><tr><td>Xoá file — <code>DELETE /files/{id}</code> (66)</td><td>⛔</td><td>⛔</td><td>✅ 🚫 (không phải chủ → 404)</td><td>✅</td></tr><tr><td>Thêm/gỡ <strong>ảnh dự án</strong> — <code>POST /admin/projects/{id}/images</code> · <code>DELETE .../images/{imageId}</code> (67/68; audit <code>PROJECT_IMAGE_ADD</code>/<code>PROJECT_IMAGE_REMOVE</code>)</td><td>⛔</td><td>⛔</td><td>⛔</td><td>✅</td></tr><tr><td>Tạo/công bố/cancel phiên đấu giá</td><td>⛔</td><td>⛔</td><td>⛔</td><td>✅</td></tr><tr><td>Đăng ký tham gia phiên + cọc</td><td>⛔</td><td>✅ (điều kiện BR-AU-05; chủ tin bị loại)</td><td>—</td><td>⛔ (admin không bid)</td></tr><tr><td>Bid</td><td>⛔</td><td>✅ 🚫 (ACTIVE registration, IN_PROGRESS)</td><td>—</td><td>⛔</td></tr><tr><td>Xem bid feed</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Đặt lịch xem</td><td>⛔</td><td>✅ (KYC APPROVED)</td><td>—</td><td>⛔</td></tr><tr><td>Confirm/reject lịch xem của tin mình</td><td>⛔</td><td>⛔</td><td>✅ 🚫</td><td>✅ (giám sát)</td></tr><tr><td>Xem/mua package</td><td>✅ (xem)</td><td>✅</td><td>—</td><td>✅ (test intent — audit)</td></tr><tr><td>Thanh toán order đấu giá</td><td>⛔</td><td>✅ 🚫 (buyer)</td><td>—</td><td>⛔</td></tr><tr><td>Confirm manual payment / CONFIRM_COMPLETED / RETRY_REFUND</td><td>⛔</td><td>⛔</td><td>⛔</td><td>✅</td></tr><tr><td>Dashboard stats / export / audit view</td><td>⛔</td><td>⛔</td><td>⛔</td><td>✅</td></tr><tr><td>Notifications của mình</td><td>⛔</td><td>✅ 🚫</td><td>—</td><td>✅ (view all cho CS)</td></tr></tbody></table><p><strong>ABAC bổ sung không nằm trong role</strong> (coder phải check cả hai tầng): KYC gate (BR-KYC-08), quota (BR-PKG-02), privilege đấu giá (BR-AU-16), trạng thái machine (§10), thời gian window (BR-AU-03/04, BR-PAY-03).</p><h2 id="_10-state-machines-bang-transition-—-nguon-cho-unit-test" tabindex="-1">10. State Machines (bảng transition — nguồn cho unit test) <a class="header-anchor" href="#_10-state-machines-bang-transition-—-nguon-cho-unit-test" aria-label="Permalink to &quot;10. State Machines (bảng transition — nguồn cho unit test)&quot;">​</a></h2><h3 id="_10-1-housing-listings-state" tabindex="-1">10.1 <code>housing_listings.state</code> <a class="header-anchor" href="#_10-1-housing-listings-state" aria-label="Permalink to &quot;10.1 `housing_listings.state`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>From \\ Event</th><th>submit</th><th>approve</th><th>reject</th><th>withdraw</th><th>publish auction</th><th>auction FAILED</th><th>order EXPIRED</th><th>order COMPLETED</th></tr></thead><tbody><tr><td>DRAFT</td><td>→IN_REVIEW</td><td>—</td><td>—</td><td>—</td><td>—</td><td></td><td></td><td></td></tr><tr><td>REJECTED</td><td>→IN_REVIEW (≤BR-HS-09)</td><td>—</td><td>—</td><td>—</td><td>—</td><td></td><td></td><td></td></tr><tr><td>IN_REVIEW</td><td>—</td><td>→LISTED</td><td>→REJECTED</td><td>⛔</td><td>⛔</td><td></td><td></td><td></td></tr><tr><td>LISTED</td><td>⛔</td><td>—</td><td>—</td><td>→WITHDRAWN</td><td>→RESERVED (qua auction PUBLISHED)</td><td></td><td></td><td></td></tr><tr><td>RESERVED</td><td>⛔</td><td>—</td><td>—</td><td>⛔</td><td>—</td><td>→LISTED</td><td>→LISTED</td><td>→SOLD</td></tr><tr><td>SOLD / WITHDRAWN</td><td>terminal</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Mọi ô ⛔ = 409 <code>INVALID_TRANSITION</code>/<code>LISTING_LOCKED</code>.</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><h3 id="_10-2-auctions-state" tabindex="-1">10.2 <code>auctions.state</code> <a class="header-anchor" href="#_10-2-auctions-state" aria-label="Permalink to &quot;10.2 `auctions.state`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>From \\ Event</th><th>publish</th><th>start job (start_at)</th><th>kết thúc job (BR-AU-13, ≥1 bid)</th><th>kết thúc (0 bid)</th><th>cancel</th></tr></thead><tbody><tr><td>DRAFT</td><td>→PUBLISHED (check BR-AU-03)</td><td>—</td><td>—</td><td>—</td><td>→CANCELLED</td></tr><tr><td>PUBLISHED</td><td>—</td><td>→IN_PROGRESS</td><td>—</td><td>—</td><td>→CANCELLED (refund)</td></tr><tr><td>IN_PROGRESS</td><td>⛔</td><td>—</td><td>→AWARDED (order tạo)</td><td>→FAILED</td><td>⛔ <code>AUCTION_CANNOT_CANCEL</code></td></tr><tr><td>AWARDED/FAILED/CANCELLED</td><td>terminal</td><td></td><td></td><td></td><td></td></tr></tbody></table><h3 id="_10-3-auction-registrations-state" tabindex="-1">10.3 <code>auction_registrations.state</code> <a class="header-anchor" href="#_10-3-auction-registrations-state" aria-label="Permalink to &quot;10.3 `auction_registrations.state`&quot;">​</a></h3><p><code>PENDING_DEPOSIT</code> →(payment SUCCESS) <code>ACTIVE</code> →(loser + refund) <code>REFUNDED</code> · →(winner order COMPLETED) <code>COMPLETED</code> · →(winner order EXPIRED) <code>FORFEITED</code> · <code>PENDING_DEPOSIT</code> →(deadline hết, chưa cọc) <code>REJECTED</code> · →(auction cancelled) <code>REFUNDED</code>/<code>REJECTED</code>.</p><h3 id="_10-4-settlement-orders-state" tabindex="-1">10.4 <code>settlement_orders.state</code> <a class="header-anchor" href="#_10-4-settlement-orders-state" aria-label="Permalink to &quot;10.4 `settlement_orders.state`&quot;">​</a></h3><p><code>PENDING</code> →(payment SUCCESS) <code>PAID</code> →(ADMIN confirm) <code>COMPLETED</code> · <code>PENDING</code> →(job payBy) <code>EXPIRED</code> · <code>PAID</code> →(ADMIN cancel+refund) <code>CANCELLED_REFUNDED</code>.</p><h3 id="_10-5-payments-state" tabindex="-1">10.5 <code>payments.state</code> <a class="header-anchor" href="#_10-5-payments-state" aria-label="Permalink to &quot;10.5 `payments.state`&quot;">​</a></h3><p><code>INITIATED</code> →(redirect/await) <code>PROCESSING</code> →(webhook/manual) <code>SUCCESS</code>|<code>FAILED</code> · <code>INITIATED|PROCESSING</code> →(job 6h) <code>EXPIRED</code> · <code>SUCCESS</code> →(refund) <code>REFUNDED</code> · webhook amount lệch → <code>RECON_FAILED</code>.</p><h3 id="_10-6-kyc-applications-state" tabindex="-1">10.6 <code>kyc_applications.state</code> <a class="header-anchor" href="#_10-6-kyc-applications-state" aria-label="Permalink to &quot;10.6 `kyc_applications.state`&quot;">​</a></h3><p><code>PENDING</code> →(approve) <code>APPROVED</code> | →(reject) <code>REJECTED</code> (terminal per application; resubmit = application mới). <code>users.kyc_status</code>: <code>NONE</code> →(submit) <code>PENDING</code> →(review) <code>APPROVED|REJECTED</code> (mirror mới nhất; resubmit REJECTED→PENDING).</p><h3 id="_10-7-user-subscriptions-state" tabindex="-1">10.7 <code>user_subscriptions.state</code> <a class="header-anchor" href="#_10-7-user-subscriptions-state" aria-label="Permalink to &quot;10.7 `user_subscriptions.state`&quot;">​</a></h3><p><code>PENDING</code> →(payment) <code>ACTIVE</code> →(ends_at) <code>EXPIRED</code> · <code>ACTIVE</code> →(mua package khác) <code>SUPERSEDED</code>; cùng package: stays ACTIVE, ends_at++.</p><h2 id="_11-bang-gioi-han-timeout-tong-hop-—-qa-dung-lam-test-data" tabindex="-1">11. Bảng giới hạn &amp; timeout (tổng hợp — QA dùng làm test data) <a class="header-anchor" href="#_11-bang-gioi-han-timeout-tong-hop-—-qa-dung-lam-test-data" aria-label="Permalink to &quot;11. Bảng giới hạn &amp; timeout (tổng hợp — QA dùng làm test data)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tham số</th><th>Giá trị</th><th>Nguồn</th></tr></thead><tbody><tr><td>Phiên truy cập đăng ký đóng</td><td>start − 24h</td><td>BR-AU-04</td></tr><tr><td>Public notice</td><td>≥ 7 ngày</td><td>BR-AU-03</td></tr><tr><td>Anti-snipe window / gia hạn</td><td>60s / 60s không giới hạn</td><td>BR-AU-12</td></tr><tr><td>Kết thúc job tick</td><td>5s; cần 60s yên lặng cuối</td><td>BR-AU-13</td></tr><tr><td>Thanh toán winner</td><td>24h</td><td>BR-AU-15</td></tr><tr><td>Hoàn cọc loser</td><td>3 ngày làm việc</td><td>BR-PAY-05</td></tr><tr><td>Payment intent TTL</td><td>6h</td><td>BR-PAY-03</td></tr><tr><td>Deposit</td><td>5% opening, min 10tr</td><td>BR-AU-06</td></tr><tr><td>Step</td><td>1–20% opening</td><td>BR-AU-09</td></tr><tr><td>Fee</td><td>1,5% default, 0–5</td><td>BR-AU-14</td></tr><tr><td>Quota tin</td><td>2/10/50</td><td>BR-PKG-01</td></tr><tr><td>CCCD attempts</td><td>3/30d; KYC→listing resubmit 5/30d</td><td>BR-KYC-06/BR-HS-09</td></tr><tr><td>Photo/doc tin</td><td>3–15 ảnh / 1–6 PDF ≤10MB</td><td>BR-HS-10</td></tr><tr><td>Upload media</td><td>ảnh ≤10MB / tài liệu ≤25MB; presign TTL 900s (env <code>S3_PRESIGN_TTL_SEC</code>, 60–604800)</td><td>BR-IDT-08 (M-003)</td></tr><tr><td>Viewing</td><td>max 3 pending, slot +24h→14d, 08–20h</td><td>BR-VW-01/02</td></tr><tr><td>SLA duyệt</td><td>KYC 48h, listing 24h, manual pay 2h</td><td>BR-ADM-03/BR-PAY-04</td></tr><tr><td>Rate limits</td><td>login 5/15p·IP, bid 1/s·user, endpoints docs/06 §3</td><td>NFR-S-02</td></tr></tbody></table><h2 id="_12-quy-trinh-đoi-rule" tabindex="-1">12. Quy trình đổi rule <a class="header-anchor" href="#_12-quy-trinh-đoi-rule" aria-label="Permalink to &quot;12. Quy trình đổi rule&quot;">​</a></h2><p>Thay đổi BR = PR vào doc này + docs/02/03/09 liên quan, <strong>PM approve bằng comment trong PR</strong>, Tech Lead merge. Không đổi rule trong code trước khi doc đổi — reviewer từ chối.</p>',41)])])}const E=d(o,[["render",i]]);export{l as __pageData,E as default};
